#include <iostream>
#include <vector>
#include <unordered_map>
#include <cmath>
#include <string>
#include <sstream>

using namespace std;

vector<int> parseLineToIntArray(const string& line) {
    vector<int> nums;
    stringstream ss(line);
    int num;
    while (ss >> num) {
        nums.push_back(num);
    }
    return nums;
}

class Cutting {
public:
    bool checkEqualEvenOdd(const vector<int>& array, int index) {
        int evenCount = 0, oddCount = 0;
        for (int i = 0; i <= index; i++) {
            if (array[i] % 2 == 0)
                evenCount++;
            else
                oddCount++;
        }
        return evenCount == oddCount;
    }

    int findNextCutIndex(const vector<int>& array, int coins, unordered_map<int, bool>& used) {
        int minIdx = -1;
        int minCost = coins + 1;
        for (int i = 1; i < (int)array.size() - 1; i++) {
            int cost = abs(array[i] - array[i + 1]);
            if (cost < minCost && checkEqualEvenOdd(array, i) && used.find(i) == used.end()) {
                minCost = cost;
                minIdx = i;
            }
        }
        return minIdx;
    }

    int getMaxNumberOfCuts(int n, int b, const vector<int>& a) {
        int coinsLeft = b;
        int cutsMade = 0;
        unordered_map<int, bool> usedIndices;
        while (coinsLeft > 0) {
            int idx = findNextCutIndex(a, coinsLeft, usedIndices);
            if (idx >= 0) {
                usedIndices[idx] = true;
                int cost = abs(a[idx] - a[idx + 1]);
                coinsLeft -= cost;
                cutsMade++;
            } else {
                break;
            }
        }
        return cutsMade;
    }
};

int main() {
    string line1, line2;
    getline(cin, line1);
    getline(cin, line2);
    vector<int> nB = parseLineToIntArray(line1);
    vector<int> a = parseLineToIntArray(line2);
    int n = nB[0];
    int b = nB[1];
    Cutting c;
    cout << c.getMaxNumberOfCuts(n, b, a) << endl;
    return 0;
}

